	LOGGER_SPEED_LAP("run")

			if (true)
	{
		std::string sArg = m_sUtf8ArgumentJSON;
		if (sArg.empty())
			sArg = "{}";
		NSStringUtils::string_replaceA(sArg, "\\", "\\\\");
