		else if (*(str + 1) == '\b') {
		    if (s->length) {
			clen = get_mclen(str + 2);
			if (plen == clen &&
			    !strncmp(str - plen, str + 2, plen)) {
			    for (i = 1; i <= plen; i++)
				*(prop - i) |= PE_BOLD;
			    str += 2 + clen;
			}
			else {
			    Strshrink(s, plen);
			    prop -= plen;
#ifdef USE_ANSI_COLOR
			    if (color)
				color -= plen;
#endif
			    if (plens == plens_buffer)
				plen = 0;
			    else
				plen = *(--plens);
